theory.exampleQuery:
WITH ranked AS (
  SELECT name, department, salary,
         DENSE_RANK() OVER (PARTITION BY department ORDER BY salary DESC) as rnk
  FROM employees
)
SELECT name, department, salary FROM ranked WHERE rnk = 1;

